"""RC2 measurement. Writer-like = a top-level def whose body contains an INSERT/UPDATE/DELETE
SQL string literal. Derive-helper use = the function (or a local helper it calls, one level) calls
a dbcore vocabulary/identifier derivation. Prints the partition; no count is hand-typed."""
import ast, re, sys
src = open(sys.argv[1]).read()
tree = ast.parse(src)
STRICT = {"check_values","check_vocab","check_declared","fk_declared","schema_choices",
          "check_expression","next_ref_id","ref_id_high_water","live_vocab"}
BROAD = STRICT | {"stamp_for","columns","exists","validate_cols","writable_tables","deletable_tables"}
SQLW = re.compile(r'\b(INSERT\s+(OR\s+\w+\s+)?INTO|UPDATE\s+"?\w+"?\s+SET|DELETE\s+FROM)\b', re.I)
funcs = {n.name: n for n in tree.body if isinstance(n, ast.FunctionDef)}
def calls(fn):
    out=set()
    for n in ast.walk(fn):
        if isinstance(n, ast.Call):
            f=n.func
            if isinstance(f, ast.Attribute) and isinstance(f.value, ast.Name) and f.value.id=="dbcore":
                out.add(("dbcore",f.attr))
            elif isinstance(f, ast.Name):
                out.add(("local",f.id))
    return out
def writes(fn):
    return any(isinstance(n, ast.Constant) and isinstance(n.value,str) and SQLW.search(n.value)
               for n in ast.walk(fn)) or any(
               isinstance(n, ast.JoinedStr) and any(isinstance(v,ast.Constant) and SQLW.search(str(v.value)) for v in n.values)
               for n in ast.walk(fn))
def uses(fn, S, depth=1, seen=None):
    seen = seen or set()
    c = calls(fn)
    if any(k=="dbcore" and a in S for k,a in c): return True
    if depth>0:
        for k,a in c:
            if k=="local" and a in funcs and a not in seen:
                seen.add(a)
                if uses(funcs[a], S, depth-1, seen): return True
    return False
W = sorted(n for n,f in funcs.items() if writes(f) and not n.startswith("_selftest"))
s_none = [n for n in W if not uses(funcs[n], STRICT)]
b_none = [n for n in W if not uses(funcs[n], BROAD)]
print(f"writer-like defs: {len(W)}")
print(f"  using NO strict derive-helper (vocab/identifier): {len(s_none)}")
print(f"  using NO helper at all (broad set incl. stamp_for/exists): {len(b_none)}")
print("  strict-none:", " ".join(s_none))
