"""Probe for the proposed RC2 detector class 3: a column whose DDL comment enumerates a
vocabulary (a|b|c) while the column declares no CHECK. Prints each hit; the count is derived."""
import re, sqlite3, sys
sys.path.insert(0, sys.argv[2])
import dbcore
con = sqlite3.connect(f"file:{sys.argv[1]}?mode=ro", uri=True)
hits = []
for name, sql in con.execute("select name, sql from sqlite_master where type='table' and sql is not null"):
    for line in sql.splitlines():
        m = re.match(r"\s*\"?(\w+)\"?\s+(TEXT|INTEGER)\b[^-]*--\s*(.*)$", line)
        if not m:
            continue
        col, _, comment = m.groups()
        if re.search(r"\b[\w.-]+(\s*\|\s*[\w.-]+){2,}", comment):
            try:
                has = bool(dbcore.check_values(con, name, col))
            except Exception:
                has = False
            if not has:
                hits.append((name, col, comment.strip()[:80]))
for h in hits:
    print("COMMENT-ONLY VOCABULARY", *h, sep="  ")
print("EXAMINED tables:", con.execute("select count(*) from sqlite_master where type='table'").fetchone()[0],
      "| hits:", len(hits))

